import nodeApis from "#node-apis";

// Optional dependencies are required in try/catch and must keep falling back.
let optional = "fallback";
try {
  optional = require("esm-require-dependency-optional").value;
} catch {}

let throws = "not thrown";
try {
  require("./throws.js");
} catch (error) {
  throws = error.message;
}

// Module-level requires run in statement order, and only when reached.
globalThis.__esmRequireDependencyConfig = "configured";
const configured = require("./configured.js").value;
if (typeof window !== "undefined") require("./browser-only.js");

function readOptional() {
  try {
    return require("esm-require-dependency-optional").value;
  } catch {
    return "fallback";
  }
}

export function readRequires() {
  // Like @clerk/nextjs's currentUser(): require() inside a function.
  require("server-only");
  const esm = require("./exports.js");
  const cjs = require("esm-require-cjs");
  // vinext resolves next/* to its shims.
  const { notFound } = require("next/navigation");
  return {
    joined: nodeApis.join("a", "b"),
    esm: `${esm.default} ${esm.named}`,
    cjs: `${cjs()} ${cjs.named}`,
    shim: typeof notFound,
    json: require("./data.json")[0],
    optional,
    nestedOptional: readOptional(),
    throws,
    configured,
    browserOnly: String(globalThis.__esmRequireBrowserOnly ?? "not evaluated"),
    shadowed: ((require) => require("./exports.js"))((id) => `local ${id}`),
  };
}
